 .hidden
.hidden{display:none!important}

 .toast
.toast{position:absolute;top:106px;left:50%;transform:translate(-50%,-10px);opacity:0;padding:10px 18px;background:rgba(15,33,26,.91);border:1px solid rgba(222,184,118,.57);font:10px 'DM Mono',monospace;letter-spacing:.06em;color:#f2dfb6;transition:all .25s}
.toast.show{opacity:1;transform:translate(-50%,0)}

 .target-tag
.target-tag{position:absolute;top:calc(50% + 28px);left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:7px 10px;background:rgba(12,24,20,.82);border:1px solid rgba(225,192,127,.56);min-width:190px;box-shadow:0 5px 20px #0c171480}
.target-tag>span{color:#e6bd77;font-size:18px}
.target-tag b,.target-tag small{display:block}
.target-tag b{font:9px 'DM Mono',monospace;letter-spacing:.08em}
.target-tag small{font:8px 'DM Mono',monospace;color:#b2bfae;margin-top:3px}
.target-tag em{margin-left:auto;font:11px 'DM Mono',monospace;color:#e6bd77;font-style:normal}

 .photo-result
.photo-result{position:absolute;left:50%;top:60%;transform:translate(-50%,10px);opacity:0;padding:10px 16px;background:rgba(14,29,23,.9);border:1px solid #dfb871;text-align:center;transition:.3s}
.camera-feedback.fired .photo-result{opacity:1;transform:translate(-50%,0)}
.photo-result b,.photo-result small{display:block}
.photo-result b{font:10px 'DM Mono',monospace;letter-spacing:.12em;color:#edcf94}
.photo-result small{font:10px 'DM Sans',sans-serif;color:#d8dfd1;margin-top:4px}

 .camera-feedback
.camera-feedback{position:absolute;inset:0;pointer-events:none}
.camera-feedback.fired .flash{animation:flash .48s ease-out}
.camera-feedback.fired .photo-result{opacity:1;transform:translate(-50%,0)}

 .prompt
.prompt{position:absolute;left:50%;bottom:18%;transform:translateX(-50%);display:flex;gap:9px;align-items:center;padding:9px 14px;background:rgba(11,23,19,.83);border:1px solid var(--line);font:9px 'DM Mono',monospace;letter-spacing:.1em}
.prompt{bottom:25%}

